import { Component } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar {
  protected order(): number {
    return 0;
  }
}

function raise(Base: typeof PctAvatar) {
  return class extends Base {
    protected override order(): number {
      return 5;
    }
  };
}

export const PctAvatarRaised = raise(PctAvatar);
